// Go CONSUMER for the `cargo` domain (contracts/wit, package
// patterncatalyst:cargo@0.1.0). It targets the contract's `cargo-consumer`
// world, which IMPORTS the three cargo interfaces; wit-bindgen-go generated the
// consumer-side bindings under internal/cargo (regenerated by build.sh). This
// file is a plain Go `main` compiled by TinyGo into a wasip1 *command* core
// module (exports `_start`). `wasm-tools component new` then adapts it with the
// wasip1 -> wasip2 *command* adapter, which synthesizes the `wasi:cli/run`
// export that invokes `_start`. Composed with ANY component that exports `cargo`
// (../rust or ../go) via `wac plug`, the result is directly `wasmtime run`-able
// with no native host.
//
// It runs the SAME deterministic scenario as the providers, the native host,
// and the Rust consumer (fixtures/scenario.json: USNYC -> DEHAM, 1200.5 kg,
// three handling events) and prints ONE normalized summary line to stdout,
// byte-identical to the Rust consumer's line. The scenario constants below MUST
// stay in lockstep with fixtures/scenario.json and consumer-rust/src/main.rs.
package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"example.com/cargo-consumer-go/internal/cargo/patterncatalyst/cargo/booking"
	"example.com/cargo-consumer-go/internal/cargo/patterncatalyst/cargo/handling"
	"example.com/cargo-consumer-go/internal/cargo/patterncatalyst/cargo/types"
)

// scenario constants — keep in lockstep with fixtures/scenario.json.
const (
	originUnlocode  = "USNYC"
	originName      = "New York"
	originCountry   = "US"
	destUnlocode    = "DEHAM"
	destName        = "Hamburg"
	destCountry     = "DE"
	arrivalDeadline = "2026-12-01T00:00:00Z"
	weightKg        = 1200.5
)

type scenarioEvent struct {
	eventType  types.HandlingEventType
	unlocode   string
	name       string
	country    string
	voyageID   string
	recordedAt string
}

func scenarioEvents() []scenarioEvent {
	return []scenarioEvent{
		{types.HandlingEventTypeReceived, "USNYC", "New York", "US", "VOY-001", "2026-11-02T09:00:00Z"},
		{types.HandlingEventTypeLoaded, "USNYC", "New York", "US", "VOY-001", "2026-11-03T14:30:00Z"},
		{types.HandlingEventTypeUnloaded, "DEHAM", "Hamburg", "DE", "VOY-001", "2026-11-20T08:15:00Z"},
	}
}

func run() (string, error) {
	spec := types.RouteSpec{
		Origin:          types.Location{Unlocode: originUnlocode, Name: originName, Country: originCountry},
		Destination:     types.Location{Unlocode: destUnlocode, Name: destName, Country: destCountry},
		ArrivalDeadline: arrivalDeadline,
	}

	// book-cargo
	b, bErr, isErr := booking.BookCargo(spec, weightKg).Result()
	if isErr {
		return "", fmt.Errorf("book-cargo: %s", bErr.String())
	}

	// get-cargo
	cargo, cErr, isErr := booking.GetCargo(b.CargoID).Result()
	if isErr {
		return "", fmt.Errorf("get-cargo: %s", cErr.String())
	}

	// request-possible-routes
	routes, rErr, isErr := booking.RequestPossibleRoutes(b.BookingID).Result()
	if isErr {
		return "", fmt.Errorf("request-possible-routes: %s", rErr.String())
	}
	itineraries := routes.Slice()
	if len(itineraries) == 0 {
		return "", fmt.Errorf("no candidate itineraries")
	}
	itinerary := itineraries[0]
	legs := itinerary.Legs.Slice()
	if len(legs) == 0 {
		return "", fmt.Errorf("itinerary has no legs")
	}
	leg := legs[0]

	// assign-route
	assigned, aErr, isErr := booking.AssignRoute(b.BookingID, itinerary).Result()
	if isErr {
		return "", fmt.Errorf("assign-route: %s", aErr.String())
	}

	// register-handling-event x3
	for _, e := range scenarioEvents() {
		loc := types.Location{Unlocode: e.unlocode, Name: e.name, Country: e.country}
		_, regErr, isErr := handling.RegisterHandlingEvent(b.CargoID, e.eventType, loc, e.voyageID, e.recordedAt).Result()
		if isErr {
			return "", fmt.Errorf("register-handling-event: %s", regErr.String())
		}
	}

	// list-handling-events
	events, lErr, isErr := handling.ListHandlingEvents(b.CargoID).Result()
	if isErr {
		return "", fmt.Errorf("list-handling-events: %s", lErr.String())
	}

	// cargo-tracker resource
	tracker := handling.NewCargoTracker(b.CargoID)
	defer tracker.ResourceDrop()
	tID := tracker.TrackingID()
	tStatus := tracker.CurrentStatus()
	tHistory := tracker.History().Slice()

	history := make([]string, 0, len(tHistory))
	for _, ev := range tHistory {
		history = append(history, ev.EventType.String()+"@"+ev.Location.Unlocode)
	}

	weight := strconv.FormatFloat(cargo.WeightKg, 'f', -1, 64)

	return fmt.Sprintf(
		"booking=%s|cargo=%s|weight=%s|price=%s %s|status=%s|itinerary=%s %s %s|assigned=%s|events=%d|tracker=%s %s %d|history=%s",
		b.BookingID,
		cargo.TrackingID,
		weight,
		b.Price.Amount,
		b.Price.Currency,
		b.Status.String(),
		itinerary.BookingID,
		leg.VoyageID,
		leg.Status.String(),
		assigned.Status.String(),
		len(events.Slice()),
		tID,
		tStatus.String(),
		len(tHistory),
		strings.Join(history, ","),
	), nil
}

func main() {
	line, err := run()
	if err != nil {
		fmt.Fprintf(os.Stderr, "cargo-consumer-go: scenario failed: %s\n", err)
		os.Exit(1)
	}
	fmt.Println(line)
}
